using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.Hazelnuts;

/// <summary>
/// Hazelnuts, from the coppiced hazel that grows in the clearings of the Mistlands; the Vikings gathered them by the
/// sackful. Model: generated by AssetSource/Tools/make_forage_models.py; the nuts hide when picked. Hares sometimes
/// carry them off.
/// </summary>
public class Hazelnuts : ForageableBase
{
    /// <summary>
    /// Prefab name of the hazelnuts item.
    /// </summary>
    public const string PrefabName = "WhiteHiltHazelnuts";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Hazelnuts";

    /// <inheritdoc/>
    protected override string Description => "Sweet brown nuts from the hazel in the clearings of the mist. They keep all winter and grind into a rich flour.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Blueberries";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "BlueberryBush";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.Mistlands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 1,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 2,
        GroupRadius = 5f,
        MinAltitude = 1f,
        MaxTilt = 25f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => null;

    /// <inheritdoc/>
    protected override string CreatureDropFrom => "Hare";

    /// <inheritdoc/>
    protected override float CreatureDropChance => 0.15f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, "hazelnuts", 0.05f);
    }

    /// <inheritdoc/>
    protected override void ApplyPickableVisual(GameObject pickablePrefab, Pickable pickable)
    {
        ReplaceBushMesh(pickablePrefab, pickable, "hazel", 1.6f);
    }
}
